//! Profile regressions on synthetic PDFs (generated by `fixtures/make_pdfs.py`). Each raster-page expectation is the
//! worker's own routing decision for that file (council review 2026-11-03, `authorizeRasterPageOcr` over pdftotext/
//! pdfimages/pdfinfo evidence), so a profile that disagrees with what the worker reads fails here.

use std::time::{Duration, Instant};

use docslurp_estimate::probe::{probe, FileProfile, PdfProfile, ProbeInput};
use docslurp_estimate::Rules;

fn probe_fixture(name: &str) -> FileProfile {
    let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    let bytes = std::fs::read(&path).unwrap_or_else(|error| panic!("{path}: {error}"));
    probe(Rules::bundled(), &ProbeInput::whole(name, None, &bytes))
}

fn pdf(result: &FileProfile) -> &PdfProfile {
    result.pdf.as_ref().unwrap_or_else(|| panic!("no page facts: {result:?}"))
}

/// Share of sampled pages the page raster rule finds held by a full-page image.
fn raster_share(result: &FileProfile) -> f64 {
    let pdf = pdf(result);
    f64::from(pdf.raster_pages) / f64::from(pdf.sampled_pages)
}

/// Every profile stays small and carries no pricing vocabulary.
fn assert_neutral(result: &FileProfile) {
    let json = serde_json::to_string(result).unwrap();
    assert!(json.len() <= 4096, "{} bytes", json.len());
    let lower = json.to_lowercase();
    for word in ["credit", "price", "priced", "bill", "rich", "fast", "cost", "free", "scanned", "mix"] {
        assert!(!lower.contains(word), "{word} in {json}");
    }
}

#[test]
fn full_page_scans_are_scanned() {
    for name in ["scan_plain.pdf", "scan_inline.pdf"] {
        assert_eq!(raster_share(&probe_fixture(name)), 1.0, "{name}");
    }
}

#[test]
fn coverage_is_measured_over_the_crop_box() {
    // MediaBox 3x the CropBox, scan filling the CropBox: the worker sees full coverage.
    assert_eq!(raster_share(&probe_fixture("scan_big_mediabox.pdf")), 1.0);
}

#[test]
fn a_title_drawn_glyph_by_glyph_does_not_hide_a_scan() {
    assert_eq!(raster_share(&probe_fixture("scan_glyph_title.pdf")), 1.0);
}

#[test]
fn text_pages_with_images_or_ocr_layers_are_not_raster_pages() {
    for name in ["scan_ocr_invisible_wrapped.pdf", "text_wrapped_with_photo.pdf"] {
        let result = probe_fixture(name);
        assert_eq!(raster_share(&result), 0.0, "{name}");
        // A large image beside a text layer is a layout-heavy page.
        assert_eq!(pdf(&result).layout_heavy_pages, 1, "{name}");
        assert_eq!(pdf(&result).text_layer_pages, 1, "{name}");
    }
}

#[test]
fn a_vector_page_in_a_text_document_is_blank_not_scanned() {
    let result = probe_fixture("vector_page_in_text_doc.pdf");
    assert_eq!(result.pages, Some(2.0));
    assert_eq!(raster_share(&result), 0.0);
    assert_eq!((pdf(&result).vector_heavy_pages, pdf(&result).layout_heavy_pages), (1, 1));
}

#[test]
fn a_form_drawn_thousands_of_times_stays_within_budget() {
    let started = Instant::now();
    let result = probe_fixture("form_amplification.pdf");
    assert!(started.elapsed() < Duration::from_secs(5), "took {:?}", started.elapsed());
    assert_eq!(result.pages, Some(1.0));
}

#[test]
fn a_page_tree_cycle_returns() {
    let _ = probe_fixture("page_tree_cycle.pdf");
}

#[test]
fn pages_without_text_and_with_only_a_small_logo_are_not_raster_pages() {
    // 20 pages, no text layer, a small logo on each: the worker routes no page to a model.
    let result = probe_fixture("no_text_small_images.pdf");
    assert_eq!(result.pages, Some(20.0));
    assert_eq!(raster_share(&result), 0.0);
    assert_eq!(pdf(&result).text_layer_pages, 0);
}

#[test]
fn every_fixture_profile_is_small_neutral_and_consistent() {
    let dir = format!("{}/tests/fixtures", env!("CARGO_MANIFEST_DIR"));
    for entry in std::fs::read_dir(&dir).unwrap() {
        let name = entry.unwrap().file_name().into_string().unwrap();
        if !name.ends_with(".pdf") {
            continue;
        }
        let result = probe_fixture(&name);
        assert_neutral(&result);
        assert_eq!(result.schema, 1);
        if let Some(pdf) = &result.pdf {
            assert_eq!(pdf.words_per_page.iter().sum::<u32>(), pdf.sampled_pages, "{name}");
            assert_eq!(pdf.image_coverage.iter().sum::<u32>(), pdf.sampled_pages, "{name}");
            for count in [pdf.text_layer_pages, pdf.low_text_pages, pdf.blank_pages, pdf.raster_pages, pdf.image_pages, pdf.layout_heavy_pages, pdf.vector_heavy_pages, pdf.unmapped_font_pages] {
                assert!(count <= pdf.sampled_pages, "{name}");
            }
        }
    }
}

/// Many object streams that each decode to 15 MiB of spaces: under lopdf's per-stream limit, far over the probe's
/// 64 MiB document budget. `type_name` and `double_flate` cover the council's bypasses of a raw-text check
/// (`#`-escaped names, nested filters).
fn object_stream_bomb(type_name: &str, double_flate: bool) -> Vec<u8> {
    let chunk = vec![b' '; 15 * 1024 * 1024];
    let mut compressed = miniz_oxide::deflate::compress_to_vec_zlib(&chunk, 9);
    if double_flate {
        compressed = miniz_oxide::deflate::compress_to_vec_zlib(&compressed, 9);
    }
    let filter = if double_flate { "[/FlateDecode /FlateDecode]" } else { "/FlateDecode" };
    let mut pdf = b"%PDF-1.7\n".to_vec();
    for number in 1..=40 {
        pdf.extend_from_slice(
            format!("{number} 0 obj\n<< /Type {type_name} /N 1 /First 4 /Filter {filter} /Length {} >>\nstream\n", compressed.len())
                .as_bytes(),
        );
        pdf.extend_from_slice(&compressed);
        pdf.extend_from_slice(b"\nendstream\nendobj\n");
    }
    pdf.extend_from_slice(b"trailer\n<< /Root 1 0 R >>\n%%EOF\n");
    pdf
}

#[test]
fn object_stream_bombs_are_refused_within_the_document_budget() {
    for (type_name, double_flate) in [("/ObjStm", false), ("/ObjSt#6D", false), ("/ObjStm", true), ("/O#62jStm", true)] {
        let pdf = object_stream_bomb(type_name, double_flate);
        let started = Instant::now();
        let result = probe(Rules::bundled(), &ProbeInput::whole("bomb.pdf", None, &pdf));
        assert!(started.elapsed() < Duration::from_secs(10), "{type_name} {double_flate}: took {:?}", started.elapsed());
        assert!(result.pdf.is_none(), "{type_name} {double_flate}");
        assert!(result.notes.iter().any(|note| note.contains("object streams")), "{type_name} {double_flate}: {:?}", result.notes);
    }
}

#[test]
fn encrypted_files_are_not_loaded() {
    let pdf = b"%PDF-1.7\n1 0 obj << /Type /Page >> endobj\ntrailer << /Root 1 0 R /Encr#79pt 2 0 R >>\n%%EOF";
    let result = probe(Rules::bundled(), &ProbeInput::whole("locked.pdf", None, pdf));
    assert_eq!(result.pages, Some(1.0));
    assert_eq!(result.encrypted, Some(true));
    assert!(result.pdf.is_none());
    assert!(result.notes.iter().any(|note| note.contains("encrypted")));
}

/// A one-page PDF with `content` as its page stream, a Helvetica font F1, and the given MediaBox (and CropBox).
fn one_page_pdf(content: &str, media: [f64; 4], crop: Option<[f64; 4]>) -> Vec<u8> {
    let boxes = format!(
        "/MediaBox [{} {} {} {}]{}",
        media[0], media[1], media[2], media[3],
        crop.map(|c| format!(" /CropBox [{} {} {} {}]", c[0], c[1], c[2], c[3])).unwrap_or_default()
    );
    let objects = [
        "<< /Type /Catalog /Pages 2 0 R >>".to_string(),
        "<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_string(),
        format!("<< /Type /Page /Parent 2 0 R {boxes} /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>"),
        format!("<< /Length {} >>\nstream\n{content}\nendstream", content.len()),
        "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding /ToUnicode 6 0 R >>".to_string(),
        "<< /Length 0 >>\nstream\n\nendstream".to_string(),
    ];
    let mut pdf = b"%PDF-1.7\n".to_vec();
    let mut offsets = Vec::new();
    for (index, body) in objects.iter().enumerate() {
        offsets.push(pdf.len());
        pdf.extend_from_slice(format!("{} 0 obj\n{body}\nendobj\n", index + 1).as_bytes());
    }
    let xref = pdf.len();
    pdf.extend_from_slice(format!("xref\n0 {}\n0000000000 65535 f \n", objects.len() + 1).as_bytes());
    for offset in offsets {
        pdf.extend_from_slice(format!("{offset:010} 00000 n \n").as_bytes());
    }
    pdf.extend_from_slice(format!("trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n", objects.len() + 1).as_bytes());
    pdf
}

const LETTER: [f64; 4] = [0.0, 0.0, 612.0, 792.0];

/// `lines` text lines of `per_line` glyphs, at `size` pt and rendering mode `mode`, starting at (x, y).
fn text_block(lines: usize, per_line: usize, size: f64, mode: u8, x: f64, y: f64) -> String {
    let line = "x".repeat(per_line);
    let mut content = format!("BT /F1 {size} Tf {mode} Tr {} TL {x} {y} Td\n", size * 1.2);
    for _ in 0..lines {
        content.push_str(&format!("({line}) Tj T*\n"));
    }
    content.push_str("ET");
    content
}

fn profile_of(bytes: &[u8]) -> PdfProfile {
    let result = probe(Rules::bundled(), &ProbeInput::whole("stuffed.pdf", None, bytes));
    assert_neutral(&result);
    result.pdf.clone().unwrap_or_else(|| panic!("no page facts: {result:?}"))
}

#[test]
fn an_ordinary_page_is_one_page_equivalent() {
    let pdf = profile_of(&one_page_pdf(&text_block(40, 60, 11.0, 0, 72.0, 720.0), LETTER, None));
    assert_eq!((pdf.sampled_chars, pdf.sampled_text_lines), (2_400, 40));
    assert_eq!(pdf.chars_by_font_size, [0, 0, 0, 2_400, 0]);
    assert_eq!((pdf.invisible_chars, pdf.off_crop_chars), (0, 0));
    assert_eq!((pdf.sampled_text_equivalents, pdf.sampled_area_equivalents, pdf.sampled_page_equivalents, pdf.max_page_equivalents), (1, 1, 1, 1));
}

#[test]
fn tiny_text_counts_the_pages_it_holds() {
    // 0.1 pt text: 400 lines of 100 glyphs (40,000 glyphs) on one page, as the billing text rule counts them.
    let pdf = profile_of(&one_page_pdf(&text_block(400, 100, 0.1, 0, 72.0, 720.0), LETTER, None));
    assert_eq!(pdf.chars_by_font_size[0], 40_000);
    // Lines rule: 400 / 60 = 7 pages; characters: 40,000 / 3,500 = 12 pages.
    assert_eq!((pdf.sampled_text_equivalents, pdf.sampled_page_equivalents, pdf.max_page_equivalents), (12, 12, 12));
}

#[test]
fn invisible_text_is_counted_and_flagged() {
    // 200 lines of 3 pt invisible text, kept on the page (3.6 pt leading from y = 760).
    let content = format!("{}\n{}", text_block(10, 50, 11.0, 0, 72.0, 720.0), text_block(200, 100, 3.0, 3, 72.0, 760.0));
    let pdf = profile_of(&one_page_pdf(&content, LETTER, None));
    assert_eq!((pdf.sampled_chars, pdf.invisible_chars), (20_500, 20_000));
    assert_eq!(pdf.sampled_page_equivalents, 6); // 20,500 / 3,500
}

#[test]
fn text_outside_the_crop_box_is_counted_and_flagged() {
    let content = format!("{}\n{}", text_block(5, 40, 11.0, 0, 72.0, 720.0), text_block(100, 100, 11.0, 0, 5_000.0, 5_000.0));
    let pdf = profile_of(&one_page_pdf(&content, [0.0, 0.0, 10_000.0, 10_000.0], Some(LETTER)));
    assert_eq!((pdf.sampled_chars, pdf.off_crop_chars), (10_200, 10_000));
    assert_eq!(pdf.sampled_page_equivalents, 3); // text rule: 10,200 / 3,500
    assert_eq!(pdf.sampled_area_equivalents, 1); // the visible (crop) box is a Letter page
}

#[test]
fn a_giant_page_counts_its_area_up_to_the_cap() {
    let inches = 200.0 * 72.0;
    let pdf = profile_of(&one_page_pdf(&text_block(2, 20, 11.0, 0, 72.0, 720.0), [0.0, 0.0, inches, inches], None));
    assert_eq!((pdf.sampled_area_equivalents, pdf.sampled_page_equivalents, pdf.max_page_equivalents), (8, 8, 8));
    let tabloid = profile_of(&one_page_pdf(&text_block(2, 20, 11.0, 0, 72.0, 720.0), [0.0, 0.0, 792.0, 1_224.0], None));
    assert_eq!(tabloid.sampled_area_equivalents, 2);
}

#[test]
fn tiny_glyphs_over_the_extraction_limit_are_dropped_as_extraction_drops_them() {
    // 60,000 glyphs of 0.1 pt: extraction keeps 50,000 a page.
    let pdf = profile_of(&one_page_pdf(&text_block(600, 100, 0.1, 0, 72.0, 720.0), LETTER, None));
    assert_eq!((pdf.sampled_chars, pdf.tiny_chars_dropped), (50_000, 10_000));
    assert_eq!(pdf.sampled_text_lines, 500);
    assert_eq!(pdf.sampled_text_equivalents, 15); // 50,000 / 3,500
    // 9-16 text pages, and dense.
    assert_eq!(pdf.text_equivalents_per_page, [0, 0, 0, 0, 1, 0, 0]);
    assert_eq!(pdf.dense_pages, 1);
    // 15 pages of text: above every allowance, so it counts in full under each.
    assert_eq!((pdf.page_equivalents_by_allowance, pdf.max_page_equivalents_by_allowance), ([15, 15, 15], [15, 15, 15]));
}

#[test]
fn text_outside_the_media_box_is_dropped_and_reported() {
    let content = format!("{}\n{}", text_block(5, 40, 11.0, 0, 72.0, 720.0), text_block(100, 100, 11.0, 0, 20_000.0, 400.0));
    let pdf = profile_of(&one_page_pdf(&content, LETTER, None));
    assert_eq!((pdf.sampled_chars, pdf.off_page_chars, pdf.off_crop_chars), (200, 10_000, 0));
    assert_eq!((pdf.sampled_page_equivalents, pdf.dense_pages), (1, 0));
}

#[test]
fn reports_page_dimensions_and_area_distribution() {
    let pdf = profile_of(&one_page_pdf(&text_block(2, 20, 11.0, 0, 72.0, 720.0), [0.0, 0.0, 792.0, 1_224.0], None));
    assert_eq!((pdf.median_page_width_pt, pdf.median_page_height_pt, pdf.max_page_width_pt, pdf.max_page_height_pt), (792, 1_224, 792, 1_224));
    assert_eq!(pdf.area_equivalents_per_page, [0, 1, 0, 0, 0, 0, 0, 0]);
    assert_eq!(pdf.text_equivalents_per_page, [1, 0, 0, 0, 0, 0, 0]);
    // Tabloid (twice Letter) with little text: its area counts in full under every allowance.
    assert_eq!((pdf.page_equivalents_by_allowance, pdf.max_page_equivalents_by_allowance), ([2, 2, 2], [2, 2, 2]));
}

#[test]
fn a_page_read_only_in_part_estimates_its_text_from_content_size() {
    // More text-showing operations than the per-page budget: the page is read in part, its glyphs estimated.
    let mut content = String::from("BT /F1 11 Tf 72 720 Td\n");
    for _ in 0..210_000 {
        content.push_str("(ab) Tj\n");
    }
    content.push_str("ET");
    let pdf = profile_of(&one_page_pdf(&content, LETTER, None));
    assert_eq!(pdf.text_estimated_pages, 1);
    assert!(pdf.budget_exhausted);
    // At least what was read: about 200,000 operations of two glyphs, estimated from the bytes interpreted.
    assert!(pdf.sampled_chars >= 400_000, "{}", pdf.sampled_chars);
    assert!(pdf.sampled_text_equivalents >= 100);
}

#[test]
fn reports_the_layout_walkers_image_facts_and_text_drawn_over_images() {
    // A scan with an invisible OCR text layer: its words sit inside the page image.
    let ocr = probe_fixture("scan_ocr_invisible_wrapped.pdf");
    let ocr = pdf(&ocr);
    assert!(ocr.glyphs_over_images > 0, "{ocr:?}");
    assert_eq!(ocr.text_over_image_pages, 1);
    assert_eq!(ocr.image_ppi.iter().sum::<u32>(), ocr.images);
    assert_eq!(ocr.image_bytes_per_pixel.iter().sum::<u32>(), ocr.images);
    // A plain scan has no text layer at all.
    let plain = probe_fixture("scan_plain.pdf");
    assert_eq!((pdf(&plain).glyphs_over_images, pdf(&plain).text_over_image_pages), (0, 0));
    assert_eq!(pdf(&plain).image_ppi.iter().sum::<u32>(), 1);
}

fn worker_fixture(name: &str) -> FileProfile {
    let path = format!("{}/../../worker/testdata/pdf-fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    let bytes = std::fs::read(&path).unwrap_or_else(|error| panic!("{path}: {error}"));
    probe(Rules::bundled(), &ProbeInput::whole(name, None, &bytes))
}

#[test]
fn counts_the_pages_the_router_reads_for_a_scan_beside_native_text() {
    // The routing eval's generated fixtures (#288): only the scan beside its caption is read.
    assert_eq!(pdf(&worker_fixture("routing-scan-beside-caption.pdf")).scan_beside_text_pages, 1);
    for name in ["routing-photo-overlaid-caption.pdf", "routing-letterhead-logo.pdf", "routing-scan-with-text-layer.pdf"] {
        assert_eq!(pdf(&worker_fixture(name)).scan_beside_text_pages, 0, "{name}");
    }
}

#[test]
fn the_allowance_applies_to_text_only_and_area_always_counts() {
    // Two pages of text on a Letter page (6,800 glyphs and 67 line breaks): 2 under allowance 1, 1 under 2 and 3.
    let two = profile_of(&one_page_pdf(&text_block(68, 100, 5.0, 0, 72.0, 720.0), LETTER, None));
    assert_eq!(two.sampled_text_equivalents, 2);
    assert_eq!(two.page_equivalents_by_allowance, [2, 1, 1]);
    // A twice-Letter page with three pages of text: text 3 is within allowance 3, but the area's 2 still counts.
    let three = profile_of(&one_page_pdf(&text_block(102, 100, 5.0, 0, 72.0, 1_100.0), [0.0, 0.0, 792.0, 1_224.0], None));
    assert_eq!((three.sampled_text_equivalents, three.sampled_area_equivalents), (3, 2));
    assert_eq!(three.page_equivalents_by_allowance, [3, 3, 2]);
}
